<script setup>
import AdminLayout from '../../AdminLayout.vue'
import { Link, router } from '@inertiajs/vue3'
defineOptions({ layout: AdminLayout })
defineProps({ q: String, renewalStatus: String, graceStatus: String, pendingPurchases: Object, pendingGraces: Object, historyPurchases: Array, historyGraces: Array })
function purchase(r, approve) {
  router.post(`/admin/requests/purchase/${r.id}/${approve ? 'approve' : 'reject'}`, { amount: r.amount, admin_note: '' })
}
function grace(r, approve) {
  router.post(`/admin/requests/grace/${r.id}/${approve ? 'approve' : 'reject'}`, { until_date: String(r.until_date).slice(0, 10), admin_note: '' })
}
</script>

<template>
  <div>
    <form method="get" class="card mb-4"><div class="card-body d-flex gap-2"><input class="form-control" name="q" :value="q" placeholder="Find pending requests by portal, mobile or email"><button class="btn btn-primary">Search</button><Link href="/admin/requests" class="btn btn-phoenix-secondary">Clear</Link></div></form>
    <div class="d-flex gap-2 mb-4"><a href="#renewals" class="btn btn-phoenix-secondary">Renewals <span class="badge badge-phoenix-warning">{{ pendingPurchases.total }}</span></a><a href="#graces" class="btn btn-phoenix-secondary">Grace periods <span class="badge badge-phoenix-warning">{{ pendingGraces.total }}</span></a></div>
    <section id="renewals" class="card mb-4"><div class="card-header d-flex justify-content-between"><h5 class="mb-0">Renewal requests</h5><span class="badge badge-phoenix-warning">{{ pendingPurchases.total }} pending</span></div><div class="card-body"><div v-for="r in pendingPurchases.data" :key="r.id" class="border-bottom py-3"><div class="d-flex justify-content-between gap-2"><div><Link :href="`/admin/portals/${r.portal.id}`" class="fw-bold">{{ r.portal.portal_name }}</Link><div>{{ r.package?.name }} · {{ r.months }} month(s) · ৳{{ r.amount }}</div><div class="small text-body-tertiary">{{ r.method }} <span v-if="r.trx_id">· {{ r.trx_id }}</span><span v-if="r.note">· {{ r.note }}</span></div></div><div class="d-flex gap-2 align-items-start"><button class="btn btn-sm btn-success" @click="purchase(r,true)">Approve</button><button class="btn btn-sm btn-outline-danger" @click="purchase(r,false)">Reject</button></div></div></div><div v-if="!pendingPurchases.data.length" class="text-body-tertiary py-3">No pending renewals.</div><div class="d-flex justify-content-between mt-3"><span>{{ pendingPurchases.total }} total</span><div class="d-flex gap-2"><Link v-if="pendingPurchases.prev_page_url" :href="pendingPurchases.prev_page_url" class="btn btn-sm btn-phoenix-secondary">Previous</Link><Link v-if="pendingPurchases.next_page_url" :href="pendingPurchases.next_page_url" class="btn btn-sm btn-phoenix-secondary">Next</Link></div></div></div></section>
    <section id="graces" class="card mb-4"><div class="card-header d-flex justify-content-between"><h5 class="mb-0">Grace period requests</h5><span class="badge badge-phoenix-warning">{{ pendingGraces.total }} pending</span></div><div class="card-body"><div v-for="r in pendingGraces.data" :key="r.id" class="border-bottom py-3 d-flex justify-content-between gap-3"><div><Link :href="`/admin/portals/${r.portal.id}`" class="fw-bold">{{ r.portal.portal_name }}</Link><div>Requested until {{ String(r.until_date).slice(0,10) }}</div><div class="small text-body-tertiary">{{ r.reason || 'No reason provided' }}</div></div><div class="d-flex gap-2 align-items-start"><button class="btn btn-sm btn-success" @click="grace(r,true)">Approve</button><button class="btn btn-sm btn-outline-danger" @click="grace(r,false)">Reject</button></div></div><div v-if="!pendingGraces.data.length" class="text-body-tertiary py-3">No pending grace requests.</div><div class="d-flex justify-content-between mt-3"><span>{{ pendingGraces.total }} total</span><div class="d-flex gap-2"><Link v-if="pendingGraces.prev_page_url" :href="pendingGraces.prev_page_url" class="btn btn-sm btn-phoenix-secondary">Previous</Link><Link v-if="pendingGraces.next_page_url" :href="pendingGraces.next_page_url" class="btn btn-sm btn-phoenix-secondary">Next</Link></div></div></div></section>
    <div class="row g-3"><section class="col-lg-6"><div class="card"><div class="card-header"><h5 class="mb-0">Recent renewal history</h5></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Portal</th><th>Plan</th><th>Amount</th><th>Status</th></tr></thead><tbody><tr v-for="r in historyPurchases" :key="r.id"><td>{{ r.portal?.portal_name }}</td><td>{{ r.package?.name }}</td><td>৳{{ r.amount }}</td><td>{{ r.status }}</td></tr><tr v-if="!historyPurchases.length"><td colspan="4" class="text-center">No history.</td></tr></tbody></table></div></div></section><section class="col-lg-6"><div class="card"><div class="card-header"><h5 class="mb-0">Recent grace history</h5></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Portal</th><th>Until</th><th>Status</th></tr></thead><tbody><tr v-for="r in historyGraces" :key="r.id"><td>{{ r.portal?.portal_name }}</td><td>{{ r.approved_until || r.until_date }}</td><td>{{ r.status }}</td></tr><tr v-if="!historyGraces.length"><td colspan="3" class="text-center">No history.</td></tr></tbody></table></div></div></section></div>
  </div>
</template>
